export function straitsSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !STRAITS_KINDS.includes(kind) || typeof mobile !== 'boolean') {
    throw new TypeError('Invalid straits SVG variant');
  }
  return FIGURES[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
